import { randomUUID } from "node:crypto";
import {
  adaptiveCertifyStratum,
  assignStrata,
  diffPrompts,
  planSampleSizes,
  seededShuffle,
  selectReuse,
  type PromptDeltaV1,
  type SivmCellInput,
  type StratumResult,
} from "@lore/core/sivm";
import {
  applyCertificateReuse,
  getCellsForVersion,
  getColumnVersion,
  saveCertificate,
