      outTok += cellOut;
      costUsd += cellCost;
      await writeCell({
        columnId: column.id,
        rowId,
        promptVersion: column.prompt_version,
        model: column.model,
        contentHash,
        status: "done",
        value: res.object.value,
        rationale: res.object.rationale.slice(0, 500),
        inputTokens: cellIn,
        outputTokens: cellOut,
        costUsd: cellCost,
        latencyMs: Date.now() - t0,
      });
      ran++;
    } catch (err) {
      errors++;
      await writeCell({
        columnId: column.id,
        rowId,
        promptVersion: column.prompt_version,
        model: column.model,
        contentHash,
        status: "error",
        error: err instanceof Error ? err.message.slice(0, 800) : String(err),
        latencyMs: Date.now() - t0,
