  assignStrata,
  diffPrompts,
  planSampleSizes,
  seededShuffle,
  selectReuse,
  type PromptDeltaV1,
  type SivmCellInput,
  type StratumResult,
} from "@lore/core/sivm";
import {
  applyCertificateReuse,
  getCellsForVersion,
  getColumnVersion,
  saveCertificate,
  type AiColumn,
} from "./column-store";
import { bindTemplate } from "./run-column";

