  }

  return {
    certificateId,
    delta,
    strata: results,
    sampledRowIds,
    reusedRowIds,
    recomputeRowIds,
    oracleCalls: revealed.size,
    observedFlips: results.reduce((a, r) => a + r.flips, 0),
